sys_script_include.script:
var DemoCaseClientUtils = Class.create();
DemoCaseClientUtils.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    getRecords: function() {
        var tableName = this.getParameter('sysparm_table');
        var query = this.getParameter('sysparm_query') || '';
        var fields = this.getParameter('sysparm_fields') || 'sys_id,title,question';

        var gr = new GlideRecord(tableName);
        if (query) {
            gr.addEncodedQuery(query);
        }
        gr.query();

        var records = [];
        while (gr.next()) {
            var record = {};
            var fieldArray = fields.split(',');
            fieldArray.forEach(function(field) {
                record[field] = gr.getDisplayValue(field) || gr.getValue(field);
            });
            records.push(record);
        }

        return JSON.stringify(records);
    },

    createRecord: function() {
        var tableName = this.getParameter('sysparm_table');
        var values = JSON.parse(this.getParameter('sysparm_values'));

        var gr = new GlideRecord(tableName);
        gr.initialize();
        for (var field in values) {
            if (values.hasOwnProperty(field)) {
                gr.setValue(field, values[field]);
            }
        }
        return gr.insert();
    },

    updateRecord: function() {
        var tableName = this.getParameter('sysparm_table');
        var sys_id = this.getParameter('sysparm_sys_id');
        var values = JSON.parse(this.getParameter('sysparm_values'));

        var gr = new GlideRecord(tableName);
        if (gr.get(sys_id)) {
            for (var field in values) {
                if (values.hasOwnProperty(field)) {
                    gr.setValue(field, values[field]);
                }
            }
            return gr.update();
        }
        return null;
    },

    deleteRecord: function() {
        var tableName = this.getParameter('sysparm_table');
        var sys_id = this.getParameter('sysparm_sys_id');

        var gr = new GlideRecord(tableName);
        if (gr.get(sys_id)) {
            return gr.deleteRecord();
        }
        return false;
    },

    _type: 'DemoCaseClientUtils'
});
